import{_ as t,o,a as r,b as n}from"./app.DII24pJb.js";const p="/ascendc.github.io/pr/6322/assets/data_vec.BgF6aaDo.png",a="/ascendc.github.io/pr/6322/assets/dbuf.CSujk_sy.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/concepts_and_terms/glossary"},{"text":"概念原理和术语","link":"/guide/technical_appendix/concepts_and_terms/glossary"},{"text":"性能优化技术原理","link":"/guide/technical_appendix/concepts_and_terms/performance_optimization/double_buffer"},{"text":"Double Buffer","link":"/guide/technical_appendix/concepts_and_terms/performance_optimization/double_buffer"}]},"headers":[],"relativePath":"guide/technical_appendix/concepts_and_terms/performance_optimization/double_buffer.md","filePath":"guide/technical_appendix/concepts_and_terms/performance_optimization/double_buffer.md","lastUpdated":1789470336000}'),c={name:"guide/technical_appendix/concepts_and_terms/performance_optimization/double_buffer.md"};function i(s,e,_,u,l,f){return o(),r("div",null,[...e[0]||(e[0]=[n('<div><article class="markdown-body"><h1>Double Buffer<span id="ZH-CN_TOPIC_0000001615270513"></span></h1><p>执行于AI Core上的指令队列主要包括如下几类，即Vector指令队列、Cube指令队列和MTE指令队列。不同指令队列间的相互独立性和可并行执行性，是Double Buffer优化机制的基石。</p><p>矢量计算CopyIn、CopyOut过程使用MTE指令队列（MTE2、MTE3），Compute过程使用Vector指令队列（V），意味着CopyIn、CopyOut过程和Compute过程是可以并行的。</p><p>如<a href="#fig994415385460">图1</a>所示，考虑一个完整的数据搬运和计算过程，CopyIn过程将数据从Global Memory搬运到Local Memory，Vector计算单元完成计算后，经过CopyOut过程将计算结果搬回Global Memory。</p><p><strong>图1</strong> 数据搬运与Vector计算过程<span id="fig994415385460"></span><br><img src="'+p+'" alt title="数据搬运与Vector计算过程"></p><p>在此过程中，数据搬运与Vector计算串行执行，Vector计算单元无可避免存在资源闲置问题。举例而言，若CopyIn、Compute、CopyOut三阶段分别耗时_t_，则Vector的时间利用率仅为1/3，等待时间过长，Vector利用率严重不足。</p><p>为减少Vector等待时间，Double Buffer机制将待处理的数据一分为二，比如Tensor1、Tensor2。如<a href="#fig189541246194710">图2</a>所示，当Vector对Tensor1中数据进行Compute时，Tensor2可以执行CopyIn的过程；而当Vector切换到计算Tensor2时，Tensor1可以执行CopyOut的过程。由此，数据的进出搬运和Vector计算实现并行执行，Vector闲置问题得以有效缓解。</p><p>总体来说，Double Buffer是基于MTE指令队列与Vector指令队列的独立性和可并行性，通过将数据搬运与Vector计算并行执行以隐藏数据搬运时间并降低Vector指令的等待时间，最终提高Vector单元的利用效率。具体实现请参见<a href="../../../operator_practice/simd_operator_optimization/pipeline_scheduling/enable_double_buffer.html">开启Double Buffer</a>。</p><p><strong>图2</strong> Double Buffer机制<span id="fig189541246194710"></span><br><img src="'+a+'" alt title="Double Buffer机制"></p><p><strong>需要注意</strong>：</p><p>多数情况下，采用Double Buffer能有效提升Vector的时间利用率，缩减算子执行时间。然而，Double Buffer机制缓解Vector闲置问题并不代表它总能带来整体的性能提升。例如：</p><ul><li>当数据搬运时间较短，而Vector计算时间显著较长时，由于数据搬运在整个计算过程中的时间占比较低，Double Buffer机制带来的性能收益会偏小。</li><li>又如，当原始数据较小且Vector可一次性完成所有计算时，强行使用Double Buffer会降低Vector计算资源的利用率，最终效果可能适得其反。</li></ul><p>因此，Double Buffer的性能收益需综合考虑Vector算力、数据量大小、搬运与计算时间占比等多种因素。</p></article></div>',1)])])}const b=t(c,[["render",i]]);export{m as __pageData,b as default};
